"""Regenerate js/pt-data.js. Requires: pip install CoolProp"""
import CoolProp.CoolProp as CP, json
G = lambda pa: round(pa / 6894.757 - 14.696, 1)
def sat(fluid, fr, F, Q):
    AS = CP.AbstractState('HEOS', fluid)
    if fr: AS.set_mole_fractions(fr)
    for d in (0, 0.01, -0.01, 0.03, -0.03):
        try:
            AS.update(CP.QT_INPUTS, Q, (F + d - 32) / 1.8 + 273.15); return G(AS.p())
        except Exception: pass
    return None
refs = {'R-410A': ('R410A', None), 'R-32': ('R32', None), 'R-22': ('R22', None), 'R-134a': ('R134a', None), 'R-454B': ('R32&R1234yf', [0.8293, 0.1707])}
temps = list(range(-40, 151, 5)); data = {}
for n, (f, fr) in refs.items():
    data[n] = {'bubble': [sat(f, fr, F, 0) for F in temps], 'dew': [sat(f, fr, F, 1) for F in temps]}
    for k in ('bubble', 'dew'):  # rare solver misses near the top of the range: fill by log-pressure interpolation
        a = data[n][k]
        for i, v in enumerate(a):
            if v is None and 0 < i < len(a) - 1 and a[i - 1] is not None and a[i + 1] is not None:
                a[i] = round(((a[i - 1] + 14.696) * (a[i + 1] + 14.696)) ** 0.5 - 14.696, 1)
    assert None not in data[n]['bubble'] + data[n]['dew'], n
# R-454B: use the refrigerant maker's published chart (Chemours Opteon XL41, C-XL41PT-ENG 7/23) instead of the CoolProp mixture model,
# which over-states the glide (~2.7 F vs Chemours ~2.3 F) and the bubble pressure by up to ~1%. tools/xl41-chemours.json holds the 1 F table.
_x = json.load(open('tools/xl41-chemours.json')); data['R-454B'] = {'bubble': _x['bubble'], 'dew': _x['dew']}
info = {
 'R-410A': {'kind': {'en': 'Near-azeotrope blend (R-32/R-125)', 'es': 'Mezcla casi azeotrópica (R-32/R-125)'}, 'glide': 0.2, 'a2l': False, 'note': {'en': 'Common residential A/C refrigerant; being phased down for new equipment under the AIM Act.', 'es': 'Refrigerante residencial común; en reducción para equipos nuevos (Ley AIM).'}},
 'R-454B': {'kind': {'en': 'Zeotropic blend (R-32/R-1234yf), A2L', 'es': 'Mezcla zeotrópica (R-32/R-1234yf), A2L'}, 'glide': 2.3, 'a2l': True, 'note': {'en': 'A2L (lower flammability) replacement for R-410A. Use DEW for superheat and BUBBLE for subcooling. Charge as liquid.', 'es': 'Reemplazo A2L (baja inflamabilidad) de R-410A. Usa ROCÍO para sobrecalentamiento y BURBUJA para subenfriamiento. Carga en líquido.'}},
 'R-32': {'kind': {'en': 'Single component, A2L', 'es': 'Un componente, A2L'}, 'glide': 0, 'a2l': True, 'note': {'en': 'A2L refrigerant used in many mini-splits and new systems.', 'es': 'Refrigerante A2L usado en minisplits y sistemas nuevos.'}},
 'R-22': {'kind': {'en': 'Single component (HCFC)', 'es': 'Un componente (HCFC)'}, 'glide': 0, 'a2l': False, 'note': {'en': 'Production ended in 2020. Older systems only; service uses recovered/reclaimed refrigerant.', 'es': 'Producción terminada en 2020. Solo sistemas viejos.'}},
 'R-134a': {'kind': {'en': 'Single component (HFC)', 'es': 'Un componente (HFC)'}, 'glide': 0, 'a2l': False, 'note': {'en': 'Common in auto A/C, chillers, and medium-temp refrigeration.', 'es': 'Común en A/C automotriz, chillers y refrigeración de media temperatura.'}}}
meta = {'temps': temps, 'source': 'Saturation values computed with CoolProp (open-source implementation of published reference equations of state, e.g. Lemmon/NIST). R-454B from Chemours Opteon XL41 P-T data (C-XL41PT-ENG 7/23). psig at sea level (14.696 psia). Negative psig = vacuum.', 'info': info}
open('js/pt-data.js', 'w').write('/* Refrigerant saturation data, generated by tools/pt-gen.py. Educational reference: verify with the refrigerant/equipment manufacturer\'s PT data. */\nwindow.PT_REF = ' + json.dumps({'meta': meta, 'data': data}, ensure_ascii=False) + ';\n')
print('ok', {n: (data[n]['bubble'][16], data[n]['dew'][16]) for n in data})
